steps.body:
A template literal type is written like a template string, between backticks, but it describes strings instead of building one. Each `${...}` holds a type: `${string}` matches any text, and `${number}` matches text that reads as a number.

```typescript
type Hex = `#${string}`;

const brand: Hex = "#336699";
console.log(brand); // #336699
```

A string literal fits when it matches the pattern, so `"blue"` is not a `Hex`. A plain `string` doesn't fit either, because it could hold anything. To turn one into a `Hex`, check it with a type guard:

```typescript
type Hex = `#${string}`;

function isHex(s: string): s is Hex {
  return s.startsWith("#");
}

const input: string = "#ffcc00";
console.log(isHex(input) ? `color ${input}` : "not a color"); // color #ffcc00
```

Patterns are loose. `${string}` also matches no text at all, so `"#"` is a `Hex` too. And the pattern only exists for the checker: at run time a `Hex` is an ordinary string.

examples.code:
type Hex = `#${string}`;

function setColor(color: Hex): string {
  return `color set to ${color}`;
}

console.log(setColor("#336699"));
console.log(setColor("blue"));

examples.explanation:
`"#336699"` starts with `#`, so the first call compiles. `"blue"` doesn't match the pattern, so the checker rejects the second call with TS2345, and nothing runs. The message writes the parameter's type as the pattern itself. Pass colors that match, and the program runs:

```typescript
type Hex = `#${string}`;

function setColor(color: Hex): string {
  return `color set to ${color}`;
}

console.log(setColor("#336699")); // color set to #336699
console.log(setColor("#fff")); // color set to #fff
```

examples.code:
type UserId = `usr_${string}`;
type TeamId = `team_${string}`;

function isUserId(s: string): s is UserId {
  return s.startsWith("usr_");
}

function isTeamId(s: string): s is TeamId {
  return s.startsWith("team_");
}

function findUser(id: UserId): string {
  return `looking up user ${id}`;
}

function findTeam(id: TeamId): string {
  return `looking up team ${id}`;
}

const incoming = ["usr_7", "team_42", "cus_3"];
for (const id of incoming) {
  if (isUserId(id)) {
    console.log(findUser(id));
  } else if (isTeamId(id)) {
    console.log(findTeam(id));
  } else {
    console.log(`unknown id ${id}`);
  }
}

examples.explanation:
Each guard checks the prefix its type promises, so in each branch `id` has the narrowed type, and the matching function accepts it. `"cus_3"` passes neither guard and lands in the `else`. The two types can't be mixed up: a `TeamId` doesn't start with `usr_`, so passing one to `findUser` is a type error:

```typescript error
type UserId = `usr_${string}`;
type TeamId = `team_${string}`;

function findUser(id: UserId): string {
  return `looking up user ${id}`;
}

const team: TeamId = "team_42";
console.log(findUser(team));
```

examples.code:
type Px = `${number}px`;

function width(value: Px): string {
  return `width: ${value};`;
}

function double(size: Px): Px {
  return `${Number.parseFloat(size) * 2}px`;
}

console.log(width("12px"));
console.log(width("0.5px"));
console.log(width("-3px"));
console.log(width(double("12px")));

examples.explanation:
`${number}` matches any text that reads as a number, so `"0.5px"` and `"-3px"` fit too. In `double`, the return type is `Px`, so the checker gives the template string a pattern type and checks it against `Px`. Without a pattern type to match, a template string is just a `string`. Text that isn't a number before `px`, or a missing `px`, is rejected:

```typescript error
type Px = `${number}px`;

const missingUnit: Px = "12";
const notANumber: Px = "widepx";
console.log(missingUnit, notANumber);
```

