type Side = "top" | "right" | "bottom" | "left";
type Margin = `margin-${Side}`;
//   ^? type Margin = "margin-bottom" | "margin-left" | "margin-right" | "margin-top"

function marginRule(side: Side, px: number): string {
  const property: Margin = `margin-${side}`;
  return `${property}: ${px}px;`;
}

const SIDES: Side[] = ["top", "right", "bottom", "left"];
for (const side of SIDES) {
  console.log(marginRule(side, side === "top" || side === "bottom" ? 16 : 8));
}

examples.explanation:
`Margin` holds the four property names, built from `Side`. In `marginRule`, the template string is checked against `Margin`, so a typo in its fixed text is a type error, and the checker even suggests the right name:

```typescript error
type Side = "top" | "right" | "bottom" | "left";
type Margin = `margin-${Side}`;

function marginRule(side: Side, px: number): string {
  const property: Margin = `marign-${side}`;
  return `${property}: ${px}px;`;
}
console.log(marginRule("top", 8));
```

