type Resource = "orders" | "products";
type Access = "read" | "write";
export type Permission = `${Resource}:${Access}`;

export function can(perms: readonly Permission[], p: Permission): boolean {
  return perms.includes(p);
}

const clerk: Permission[] = ["orders:read", "products:read", "products:write"];
const checks: Permission[] = ["orders:read", "orders:write", "products:write"];

for (const p of checks) {
  console.log(`${p} is ${can(clerk, p) ? "allowed" : "denied"}`);
}

steps.body:
`infer` works inside template literal types too. Write the shape of the string as a pattern, and each `infer` names the piece it matches:

```typescript types
type Split<S> = S extends `${infer Head}.${infer Tail}` ? [Head, Tail] : [S];

type Event = Split<"order.created">;
//   ^? type Event = ["order", "created"]
type Nested = Split<"order.item.added">;
//   ^? type Nested = ["order", "item.added"]
```

Each placeholder takes the text up to the first place where the next fixed part appears, and the last one takes the rest. That's why `Head` stops at the first dot.

To walk a whole string, a type can refer to itself inside a branch of a conditional type: handle the first piece, then apply the same type to the rest, until a branch stops. That's how a route pattern like `/orders/:orderId/items/:itemId` becomes the parameter names `"itemId" | "orderId"`, and how a function can demand an object with exactly those keys. Express's type definitions type `req.params` this way.

examples.code:
type ParamName<S> = S extends `:${infer P}` ? P : never;

type OrderParam = ParamName<":orderId">;
//   ^? type OrderParam = "orderId"
type Fixed = ParamName<"orders">;
//   ^? type Fixed = never

function paramName(segment: string): string | null {
  return segment.startsWith(":") ? segment.slice(1) : null;
}

const segments = "/orders/:orderId".split("/").filter((s) => s !== "");
for (const segment of segments) {
  const name = paramName(segment);
  console.log(name === null ? `${segment} is fixed text` : `${segment} is the parameter ${name}`);
}

type ExtractParams<P extends string> =
  P extends `${string}:${infer Param}/${infer Rest}`
    ? Param | ExtractParams<Rest>
    : P extends `${string}:${infer Param}`
      ? Param
      : never;

type ItemParams = ExtractParams<"/orders/:orderId/items/:itemId">;
//   ^? type ItemParams = "itemId" | "orderId"
type HealthParams = ExtractParams<"/health">;
//   ^? type HealthParams = never

function paramNames(pattern: string): string[] {
  return pattern
    .split("/")
    .filter((segment) => segment.startsWith(":"))
    .map((segment) => segment.slice(1));
}

for (const pattern of ["/orders/:orderId/items/:itemId", "/users/:id", "/health"]) {
  console.log(`${pattern}: ${paramNames(pattern).join(", ") || "no params"}`);
}

type PathParams<P extends string> =
  P extends `${string}{${infer Name}}${infer Rest}` ? Name | PathParams<Rest> : never;

function fillPath<P extends string>(pattern: P, params: Record<PathParams<P>, string>): string {
  const values: Record<string, string> = params;
  return pattern
    .split("/")
    .map((segment) => {
      if (!segment.startsWith("{") || !segment.endsWith("}")) return segment;
      return values[segment.slice(1, -1)] ?? segment;
    })
    .join("/");
}

console.log(fillPath("/users/{id}", { id: "42" }));
console.log(fillPath("/orders/{orderId}/items/{itemId}", { orderId: "ord_1001" }));

examples.explanation:
`P` is inferred from the pattern each call passes, so for the second call `PathParams<P>` is `"itemId" | "orderId"`, and `params` must have both keys. The call leaves out `itemId`, which is TS2741, and nothing runs.

Inside the function, `params[name]` with a `name` of type `string` would be an error, because the checker only knows the keys in `PathParams<P>`. So the function reads the same object through `values`, a `Record<string, string>`, where any key is allowed and each value is `string | undefined`. No cast is needed, since an object with known string keys is also a record of strings. Pass every value, and it runs:

```typescript
type PathParams<P extends string> =
  P extends `${string}{${infer Name}}${infer Rest}` ? Name | PathParams<Rest> : never;

function fillPath<P extends string>(pattern: P, params: Record<PathParams<P>, string>): string {
  const values: Record<string, string> = params;
  return pattern
    .split("/")
    .map((segment) => {
      if (!segment.startsWith("{") || !segment.endsWith("}")) return segment;
      return values[segment.slice(1, -1)] ?? segment;
    })
    .join("/");
}

console.log(fillPath("/orders/{orderId}/items/{itemId}", { orderId: "ord_1001", itemId: "3" })); // /orders/ord_1001/items/3
```

