type ExtractParams<P extends string> =
  P extends `${string}:${infer Param}/${infer Rest}`
    ? Param | ExtractParams<Rest>
    : P extends `${string}:${infer Param}`
      ? Param
      : never;

export function buildPath<P extends string>(pattern: P, params: Record<ExtractParams<P>, string>): string {
  const values: Record<string, string> = params;
  return pattern
    .split("/")
    .map((segment) => (segment.startsWith(":") ? (values[segment.slice(1)] ?? segment) : segment))
    .join("/");
}

console.log(buildPath("/users/:id", { id: "42" }));
console.log(buildPath("/orders/:orderId/items/:itemId", { orderId: "ord_1001", itemId: "3" }));
